+          // listener popping the sheet — same instantaneous-state
+          // rationale as `_AudioTab`'s own `AudioSaved` branch (reuses
+          // the same `_AudioLoading` spinner).
+          PhotoSaved() => const _AudioLoading(),
+        };
+      },
+    );
+  }
